    values (x->>0, x->>1, x->>2, (x->>3)::int, x->>4, (x->>5)::numeric, x->>6,
      now() + make_interval(secs => (x->>7)::int),
      case when x->>8 is null then null else now() + make_interval(secs => (x->>8)::int) end,
      case when x->>9 is null then null else now() + make_interval(secs => (x->>9)::int) end,
      case when x->>10 is null then null else now() + make_interval(secs => (x->>10)::int) end,
      x->>11,
      coalesce((select jsonb_agg(jsonb_build_object('by', (select id from profiles where handle = a->>0), 'ts', now() + make_interval(secs => (a->>1)::int)))
                from jsonb_array_elements(x->12) a), '[]'::jsonb));
  end loop;
  for x in select value from jsonb_array_elements('[[-2505600,"u-co","Changed condition","FP-10420","serviceable → quarantined · Form 1 serial does not match data plate"],[-1555200,"u-pm","Approved purchase order","PO-7001","Second-level approval · USD 62,000"],[-259200,"u-ad","Assigned location scope","J. Patel","LHR → LHR, DXB"]]'::jsonb) loop
    insert into audit(ts, by_user, action, object, detail)
    values (now() + make_interval(secs => (x->>0)::int), (select id from profiles where handle = x->>1), x->>2, x->>3, x->>4);
  end loop;
  insert into settings(key, value) values ('limit', '5000'::jsonb) on conflict (key) do update set value = excluded.value;
end $$;

create or replace function public.reset_demo() returns text
language plpgsql security definer set search_path = public as $$
declare r profiles := _me();
begin
  if r.role not in ('admin', 'superadmin') then raise exception 'Only the Admin can reset the demo.'; end if;
  truncate events, items, requests, pos, rec_decisions, tasks, audit restart identity;
  delete from settings;
  alter sequence po_seq restart with 7005; alter sequence trf_seq restart with 433; alter sequence req_seq restart with 3303;
  perform seed_demo();
  perform _audit(r.id, 'Reset demo data', 'Database', 'Reseeded to the starting scenario');
  return 'Demo data reset to the seeded starting point.';
end $$;

-- Only the listed functions can be called from the app, and only by signed-in users.
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.my_role(), public.my_supplier() to authenticated;
grant execute on function public.ingest(jsonb), public.scanner_tick(), public.raise_request(text, text, text, text, text),
  public.approve_rec(text, text, text, int), public.reject_rec(text), public.lateral_transfer(text, text, text, text, int),
  public.send_task(bigint), public.receive_po(text), public.issue_reserved(text, text), public.supplier_po(text, text),
  public.propose_limit(numeric), public.decide_limit(boolean), public.reset_demo() to authenticated;
grant usage, select on all sequences in schema public to authenticated;

alter publication supabase_realtime add table public.events, public.requests, public.pos, public.rec_decisions, public.tasks, public.settings;
